def game_score(points: str) -> str:
    a_points = 0
    b_points = 0

    for point in points:
        # Check if game is already won
        if a_points >= 4 and a_points > b_points:
            return "Game A"
        if b_points >= 4 and b_points > a_points:
            return "Game B"

        # Award the point
        if point == 'A':
            a_points += 1
        elif point == 'B':
            b_points += 1

    # Check for game win after all points
    if a_points >= 4 and a_points > b_points:
        return "Game A"
    if b_points >= 4 and b_points > a_points:
        return "Game B"

    # Convert to tennis score
    score_map = {0: '0', 1: '15', 2: '30', 3: '40'}

    # Handle 40-40 (deuce) case with no-ad scoring
    if a_points >= 3 and b_points >= 3:
        return "40-40"

    a_score = score_map[a_points]
    b_score = score_map[b_points]

    return f"{a_score}-{b_score}"
